"""Helpers for cleaning and summarising a weather station's daily readings."""

MISSING = {"", "n/a", "-"}
COLUMNS = ("max_c", "min_c", "rain_mm")


def parse_float(text):
    """Return text as a float, or None if it's a missing-value marker.

    Raises ValueError if the text is neither a number nor a marker.
    """
    text = text.strip()
    if text in MISSING:
        return None
    return float(text)


def parse_reading(row):
    # TODO: write a docstring: what the function takes, what it returns and what it raises
    reading = {"date": row["date"].strip()}
    for column in COLUMNS:
        # TODO: a short row gives None for the missing columns: raise ValueError(f"missing value for {column}")
        reading[column] = parse_float(row[column])
    return reading


def classify(max_c):
    """Label a day by its maximum temperature; 'unknown' when there's no maximum."""
    if max_c is None:
        return "unknown"
    if max_c >= 30:
        return "hot"
    if max_c >= 20:
        return "warm"
    if max_c >= 10:
        return "mild"
    return "cool"


def summarise(days):
    """Return a dict of summary numbers for a list of readings."""
    maxima = [d["max_c"] for d in days if d["max_c"] is not None]
    rain = [d["rain_mm"] for d in days if d["rain_mm"] is not None]
    hottest = max((d for d in days if d["max_c"] is not None), key=lambda d: d["max_c"])
    types = {}
    # TODO: count the days of each type, using classify()
    return {
        "days": len(days),
        "no_max": len(days) - len(maxima),
        "mean_max": sum(maxima) / len(maxima),
        "hottest": hottest,
        "total_rain": sum(rain),
        "rain_days": 0,  # TODO: the number of days with more than 0 mm of rain
        "types": types,
    }
